function t(key){
  return (I18N[LANG] && I18N[LANG][key] !== undefined) ? I18N[LANG][key] : (I18N.it[key] !== undefined ? I18N.it[key] : key);
}
function translateStatic(){
  document.querySelectorAll('[data-i18n]').forEach(el => { el.textContent = t(el.getAttribute('data-i18n')); });
  document.querySelectorAll('[data-i18n-html]').forEach(el => { el.innerHTML = t(el.getAttribute('data-i18n-html')); });
  document.querySelectorAll('[data-i18n-ph]').forEach(el => { el.setAttribute('placeholder', t(el.getAttribute('data-i18n-ph'))); });
  const titleByLang = { it: 'Confronta Prodotti per Gelateria', de: 'Eisdielen Zutatenvergleich: Basen, Pasten und Halbfertigprodukte im Vergleich', en: 'Compare Gelato Products', es: 'Compara Productos para Heladería' };
  document.title = titleByLang[LANG] || titleByLang.it;
  const metaDesc = document.querySelector('meta[name="description"]');
  const descByLang = {
    it: 'Strumento per confrontare ingredienti, fornitori e parametri tecnici per gelateria',
    de: 'Kostenloser Zutatenvergleich für Eisdielen ohne Registrierung: Vergleiche Basen, Pasten und Halbfertigprodukte verschiedener Hersteller — PAC, POD, Trockenmasse und Richtpreise, direkt nebeneinander.',
    en: 'Tool to compare ingredients, suppliers and technical parameters for gelato shops',
    es: 'Herramienta para comparar ingredientes, proveedores y parámetros técnicos para heladerías',
  };
  if (metaDesc) metaDesc.setAttribute('content', descByLang[LANG] || descByLang.it);
  document.documentElement.setAttribute('lang', LANG);
  const y = document.getElementById('copyYear');
  if (y) y.textContent = String(currentYear);
}
let currentYear = 2026;
function setLang(lang){
  LANG = 'de';
  try { localStorage.setItem('preferredLang', LANG); } catch (e) {}
  translateStatic();
  const resultCard = document.getElementById('resultCard');
  const wasCompareVisible = resultCard && resultCard.style.display !== 'none';
  if (typeof refreshCategorySelect === 'function') refreshCategorySelect();
  if (typeof refreshDatalists === 'function') refreshDatalists();
  if (typeof refreshPickerColumns === 'function') refreshPickerColumns(); // nota: nasconde resultCard come effetto collaterale
  if (typeof renderArchiveTable === 'function') renderArchiveTable();
  if (typeof refreshRicettaAddSelect === 'function') refreshRicettaAddSelect();
  if (typeof renderRicettaTable === 'function') renderRicettaTable();
  if (typeof renderCurvaTable === 'function') renderCurvaTable();
  if (typeof renderPostazioniTable === 'function') renderPostazioniTable();
  if (wasCompareVisible && typeof buildCompareTable === 'function') buildCompareTable();
  if (typeof refreshExtraToolsButtonLabel === 'function') refreshExtraToolsButtonLabel();
  if (typeof renderAziende === 'function') renderAziende();
}
window.setLang = setLang;

function refreshExtraToolsButtonLabel(){
  const btn = document.getElementById('btnToggleExtraTools');
  const el = document.getElementById('extraTools');
  if (!btn || !el) return;
  const isOpen = el.style.display !== 'none';
  btn.textContent = isOpen ? t('btnHideExtraTools') : t('btnShowExtraTools');
}
function toggleExtraTools(forceOpen){
  const el = document.getElementById('extraTools');
  if (!el) return;
  const isOpen = el.style.display !== 'none';
  const open = forceOpen !== undefined ? forceOpen : !isOpen;
  el.style.display = open ? '' : 'none';
  refreshExtraToolsButtonLabel();
}
window.toggleExtraTools = toggleExtraTools;
function openExtraToolsIfNeeded(targetId){
  if (targetId === 'taraturaCard' || targetId === 'postazioniCard' || targetId === 'documentiCard'){
    toggleExtraTools(true);
  }
}
window.openExtraToolsIfNeeded = openExtraToolsIfNeeded;

function closeSection(id){
  const el = document.getElementById(id);
  if (el) el.style.display = 'none';
}
window.closeSection = closeSection;
function openSection(id){
  const el = document.getElementById(id);
  if (el) el.style.display = '';
}
window.openSection = openSection;

function toggleDocPanel(){
  const panel = document.getElementById('docPanelDE');
  if (panel) panel.classList.toggle('open');
  if (panel && panel.classList.contains('open')) panel.scrollIntoView({ behavior:'smooth', block:'nearest' });
}
window.toggleDocPanel = toggleDocPanel;

currentYear = new Date().getFullYear();
document.addEventListener('DOMContentLoaded', () => {
  const y = document.getElementById('copyYear');
  if (y) y.textContent = String(currentYear);
});

