function aziendaColorFor(azienda){
  if(AZIENDA_COLORS[azienda]) return AZIENDA_COLORS[azienda];
  // fallback deterministico per aziende non ancora in palette: colore stabile ma distinto
  let hash = 0;
  for(let i=0;i<azienda.length;i++){ hash = (hash*31 + azienda.charCodeAt(i)) >>> 0; }
  const hue = hash % 360;
  return `hsl(${hue}, 55%, 34%)`;
}
