// ---------- Helpers ----------
function uniqueSorted(arr){ return [...new Set(arr)].filter(Boolean).sort((a,b)=>a.localeCompare(b,'it')); }
function fmtVal(v){ if(v === null || v === undefined || v === "" || v === "n.d.") return `<span class="empty-val">${t('emptyVal')}</span>`; return v; }
function escAttr(s){ return String(s).replace(/"/g,'&quot;'); }
function fmtFonte(url){ if(!url) return null; return `<a class="source-link" href="${escAttr(url)}" target="_blank" rel="noopener">${t('sourceLink')}</a>`; }
function stars(v){
  if(!v) return `<span class="empty-val">${t('daValutareStar')}</span>`;
  const n = parseInt(v,10);
  return '<span class="stars">' + '★'.repeat(n) + '☆'.repeat(5-n) + '</span>';
}
function showToast(msg){ const t = document.getElementById('toast'); t.textContent = msg; t.classList.add('show'); setTimeout(()=> t.classList.remove('show'), 2200); }

function animateStatTo(el, target){
  target = Number(target) || 0;
  var start = parseInt((el.textContent||'0').replace(/[^0-9]/g,''),10) || 0;
  if(start === target){ el.textContent = target; return; }
  var t0 = null, dur = 700;
  function step(ts){
    if(!t0) t0 = ts;
    var p = Math.min((ts - t0) / dur, 1);
    var val = Math.round(start + (target - start) * p);
    el.textContent = val;
    if(p < 1) requestAnimationFrame(step); else el.textContent = target;
  }
  requestAnimationFrame(step);
}
function refreshStats(){
  animateStatTo(document.getElementById('statAziende'), uniqueSorted(archivio.map(e=>e.azienda)).length);
  animateStatTo(document.getElementById('statProdotti'), archivio.length);
  animateStatTo(document.getElementById('statCategorie'), CATEGORIES.length);
}

