  const prev = sel.value;
  sel.innerHTML = CATEGORIES.map(c=>`<option value="${c}">${catIcon(c)} ${c}</option>`).join('');
  if(CATEGORIES.includes(prev)) sel.value = prev;

  const filterSel = document.getElementById('filterArchiveCategoria');
  const prevFilter = filterSel.value;
  filterSel.innerHTML = `<option value="">${t('tutte')}</option>` + CATEGORIES.map(c=>`<option value="${c}">${catIcon(c)} ${c}</option>`).join('');
  filterSel.value = prevFilter;

