let deferredInstallPrompt = null;
const btnInstall = document.getElementById('btnInstall');

window.addEventListener('beforeinstallprompt', (e) => {
  e.preventDefault();
  deferredInstallPrompt = e;
  btnInstall.style.display = 'inline-flex';
  const androidHintEl = document.getElementById('androidInstallHint');
  if (androidHintEl) androidHintEl.style.display = 'none';
});

btnInstall.addEventListener('click', async () => {
  if (!deferredInstallPrompt) return;
  btnInstall.style.display = 'none';
  deferredInstallPrompt.prompt();
  await deferredInstallPrompt.userChoice;
  deferredInstallPrompt = null;
});

window.addEventListener('appinstalled', () => {
  btnInstall.style.display = 'none';
  showToast(t('toastAppInstallata'));
});

// iOS/Safari non supporta beforeinstallprompt: mostra istruzioni manuali
// se sembra iOS e l'app non è già in modalità standalone.
(function () {
  const ua = navigator.userAgent;
  const isIOS = /iphone|ipad|ipod/i.test(ua);
  const isStandalone = window.matchMedia('(display-mode: standalone)').matches || window.navigator.standalone === true;
  if (isStandalone) return;
  if (isIOS) {
    document.getElementById('iosInstallHint').style.display = 'block';
    return;
  }
  // Android e desktop: Chrome a volte ritarda/non mostra 'beforeinstallprompt' (criteri di engagement,
  // tempo trascorso sul sito) e i browser non Chromium (Samsung Internet, Firefox, Edge in alcuni casi...)
  // non lo supportano affatto. Se dopo un breve attimo non è ancora apparso il bottone nativo,
  // mostriamo istruzioni manuali valide sia su telefono che su computer.
  setTimeout(() => {
    if (!deferredInstallPrompt && btnInstall.style.display === 'none') {
      document.getElementById('androidInstallHint').style.display = 'block';
    }
  }, 2500);
})();

// ------- Modulo "Unisciti a noi" (Netlify Forms, senza backend) -------
(function () {
  const overlay = document.getElementById('joinModalOverlay');
  const form = document.getElementById('joinForm');
  const btnOpen = document.getElementById('btnJoinUs');
  const btnClose = document.getElementById('joinModalClose');

  function openModal(){ overlay.classList.add('open'); document.body.style.overflow = 'hidden'; }
  function closeModal(){ overlay.classList.remove('open'); document.body.style.overflow = ''; }

  btnOpen.addEventListener('click', openModal);
  btnClose.addEventListener('click', closeModal);
  overlay.addEventListener('click', (e) => { if (e.target === overlay) closeModal(); });
  document.addEventListener('keydown', (e) => { if (e.key === 'Escape' && overlay.classList.contains('open')) closeModal(); });

  form.addEventListener('submit', function (e) {
    e.preventDefault();
    const submitBtn = form.querySelector('button[type="submit"]');
    const originalLabel = submitBtn.textContent;
    submitBtn.disabled = true;
    submitBtn.textContent = t('joinSubmitting');
    const body = new URLSearchParams(new FormData(form)).toString();
    fetch('/', {
      method: 'POST',
      headers: { 'Content-Type': 'application/x-www-form-urlencoded' },
      body,
    })
      .then((response) => {
        if (!response.ok) throw new Error('Invio non riuscito: ' + response.status);
        showToast(t('toastJoinSuccess'));
        closeModal();
        form.reset();
      })
      .catch(() => {
        showToast(t('toastJoinError'));
      })
      .finally(() => {
        submitBtn.disabled = false;
        submitBtn.textContent = originalLabel;
      });
  });
})();

