(function(){
  var selector = '.card';
  var els = document.querySelectorAll(selector);
  function revealAll(){ els.forEach(function(c){ c.classList.add('in-view'); }); }
  if (!('IntersectionObserver' in window)) {
    revealAll();
    return;
  }
  try {
    var io = new IntersectionObserver(function(entries){
      entries.forEach(function(entry){
        if (entry.isIntersecting) {
          entry.target.classList.add('in-view');
          io.unobserve(entry.target);
        }
      });
    }, { threshold: 0.12, rootMargin: '0px 0px -40px 0px' });
    els.forEach(function(c){ io.observe(c); });
  } catch (err) {
    revealAll();
    return;
  }
  // Rete di sicurezza: se per qualsiasi motivo l'osservatore non scatta
  // (browser particolari, tab in background, estensioni, ecc.), mostriamo
  // comunque tutto dopo un breve ritardo, cosi il contenuto non resta mai
  // invisibile.
  setTimeout(revealAll, 1500);
})();
